                    Err(ApiErrorResponse::IntegrityCheckFailed {
                        reason: "capturable_amount is less than the total attempt amount"
                            .to_string(),
                        field_names: "amount_capturable".to_string(),
                        connector_transaction_id: payment_data
                            .payment_attempt
