        &self,
        payment_data: &PaymentData<F>,
        amount_captured: Option<i64>,
        amount_capturable: Option<i64>,
    ) -> CustomResult<enums::AttemptStatus, ApiErrorResponse>
    where
        F: Clone,
    {
