                if payment_data.payment_intent.amount_captured > Some(MinorUnit::new(0)) {
                    Ok(enums::AttemptStatus::PartialCharged)
                } else {
                    Ok(self.status)
                }
            }
            enums::AttemptStatus::Charged => {
                let captured_amount = types::Capturable::get_captured_amount(
                    &self.request,
                    amount_captured,
